'use strict';
const Module = require('module');
const fs = require('fs');
const { isDeepStrictEqual: equal } = require('util');
const original_load = Module._load;
let recorded = 0;
Module._load = function(request, parent, ...args) {
	const value = original_load.call(this, request, parent, ...args);
	if (request !== './btp_sync_locks/resources' || !parent?.filename.startsWith('/tmp/bts-queue-responsiveness-') ||
		!parent.filename.endsWith('/server-0/bts/btp_sync_plan.js')) return value;
	const ordering = parent.require('./btp_sync_locks/ordering_only');
	return function(key, before, changes, effects) {
		const scope = value(key, before, changes, effects);
		if (scope.diagnostics.allocation_scope === 'ordering_only' || recorded++ >= 64) return scope;
		const ids = new Set(changes.map(change => change.id));
		const docs = new Map(before.matches.map(match => [match._id, match]));
		const non_ordering = changes.filter(change => !ordering([change], []));
		const excluded = effects.filter(effect => !ordering(changes, [effect]));
		const row = { ts: Date.now(), scope: scope.diagnostics, changes: changes.length, effects: effects.length,
			non_ordering_changes: non_ordering.slice(0, 6).map(change => ({ id: change.id, collection: change.collection,
				set: Object.keys(change.update?.$set || {}), unset: Object.keys(change.update?.$unset || {}) })),
			non_ordering_count: non_ordering.length,
			excluded_effects: excluded.slice(0, 6).map(effect => { const note = effect.resources.notification;
				const id = note?.value?.match__id || note?.value?._id;
				return { resources: Object.keys(effect.resources), type: note?.ctype, id,
					direct_change: ids.has(id), known_match: docs.has(id),
					unchanged_full_payload: equal(docs.get(id), note?.value?.match), payload_fields: Object.keys(note?.value || {}) };
			}), excluded_count: excluded.length };
		fs.appendFileSync('/tmp/bts-plan-rejections-diagnostic.jsonl', JSON.stringify(row) + '\n');
		return scope;
	};
};

cpu_diagnosis.observer_source:
'use strict';
// Diagnostic only: target the benchmark's owned, immutable server archive.
if (process.argv[1]?.endsWith('/queue_responsiveness/mixed_server.js')) {
	const fs = require('fs');
	const path = require('path');
	const options = JSON.parse(process.argv[2]);
	const root = fs.realpathSync(options.root);
	const directory = fs.realpathSync(options.directory);
	if (path.dirname(path.dirname(root)) !== fs.realpathSync('/tmp') ||
		!path.basename(path.dirname(root)).startsWith('bts-queue-responsiveness-') ||
		path.basename(root) !== 'server-0' || path.dirname(directory) !== path.dirname(root)) {
		throw new Error('CPU profiler requires own temporary benchmark archive');
	}
	const session = new (require('inspector').Session)();
	session.connect();
	session.post('Profiler.enable');
	session.post('Profiler.setSamplingInterval', { interval: 1000 });
	let started = false;
	const clocks = {};
	process.on('message', message => {
		if (message.type !== 'start' || started) return;
		started = true;
		clocks.start_wall_ms = Date.now();
		clocks.start_ns = String(process.hrtime.bigint());
		session.post('Profiler.start');
	});
	const send = process.send.bind(process);
	process.send = (message, ...args) => {
		if (message.type !== 'done' || !started) return send(message, ...args);
		started = false;
		clocks.end_wall_ms = Date.now();
		clocks.end_ns = String(process.hrtime.bigint());
		session.post('Profiler.stop', (error, result) => {
			if (error) throw error;
			fs.writeFileSync(path.join(directory, 'server.cpuprofile'), JSON.stringify(result.profile));
			fs.writeFileSync(path.join(directory, 'cpu-profile-clocks.json'), JSON.stringify(clocks));
			session.disconnect();
			send(message, ...args);
		});
	};
}

announcement_boundaries_diagnosis.observer_source:
'use strict';

const path = require('path');
const fs = require('fs');
const entry = process.argv[1] || '';
if (/\/queue_responsiveness\/mixed_(server|receiver)\.js$/.test(entry)) {
	const options = JSON.parse(process.argv[2]);
	const directory = fs.realpathSync(options.directory);
	const job = path.dirname(directory);
	if (path.dirname(job) !== fs.realpathSync('/tmp') || !path.basename(job).startsWith('bts-queue-responsiveness-')) {
		throw new Error('Signal observer requires own temporary benchmark directory');
	}
	const send = process.send.bind(process);
	if (entry.endsWith('/mixed_server.js')) {
		const root = fs.realpathSync(options.root);
		if (path.dirname(root) !== job || path.basename(root) !== 'server-0') throw new Error('Not an owned archive');
		const Module = require('module'), load = Module._load;
		const patched = new WeakSet(), connections = new WeakMap(), records = [];
		let connection = 0;
		Module._load = function(request, parent, isMain) {
			const mod = load.call(this, request, parent, isMain);
			if (!/\/(admin|wshandler)(\.js)?$/.test(request)) return mod;
			const filename = Module._resolveFilename(request, parent);
			if (!filename.startsWith(root + '/bts/') || patched.has(mod)) return mod;
			if (filename === root + '/bts/admin.js' && typeof mod.handle_free_announce === 'function') {
				patched.add(mod);
				const handle = mod.handle_free_announce;
				mod.handle_free_announce = function(app, ws, message) {
					const record = { type: 'handler', rid: message.rid, connection: connections.get(ws),
						start_ns: String(process.hrtime.bigint()) };
					records.push(record);
					try { return handle.call(this, app, ws, message); }
					finally { record.end_ns = String(process.hrtime.bigint()); record.outbox = ws.outbox_stats(); record.buffered_bytes = ws.bufferedAmount; }
				};
			}
			if (filename === root + '/bts/wshandler.js' && typeof mod.handle === 'function') {
				patched.add(mod);
				const handle = mod.handle;
				mod.handle = function(mod, app, ws) {
					connections.set(ws, ++connection);
					const original = ws.send;
					ws.send = function(bytes, ...args) {
						// Inspect only small announcement payloads; never parse snapshots.
						if (typeof bytes === 'string' && bytes.length < 2048 && bytes.includes('"ctype":"free_announce"')) {
							const message = JSON.parse(bytes);
							const start = process.hrtime.bigint();
							records.push({ type: 'send', rid: message.val._announcement_claim_key,
								connection: connections.get(ws), start_ns: String(start), buffered_bytes: ws.bufferedAmount });
						}
						return original.call(this, bytes, ...args);
					};
					return handle.call(this, mod, app, ws);
				};
			}
			return mod;
		};
		process.send = (message, ...args) => {
			if (message.type === 'done') fs.writeFileSync(path.join(directory, 'announcement-boundaries.json'), JSON.stringify(records));
			return send(message, ...args);
		};
	} else {
		const session = new (require('inspector').Session)();
		session.connect(); session.post('Profiler.enable'); session.post('Profiler.setSamplingInterval', { interval: 1000 });
		let started = false;
		process.on('message', message => {
			if (message.type !== 'start' || started) return;
			started = true; session.post('Profiler.start');
		});
		process.send = (message, ...args) => {
			if (message.type !== 'done' || !started) return send(message, ...args);
			started = false;
			session.post('Profiler.stop', (error, result) => {
				if (error) throw error;
				fs.writeFileSync(path.join(directory, 'receiver.cpuprofile'), JSON.stringify(result.profile));
				session.disconnect(); send(message, ...args);
			});
		};
	}
}
